test "linker kernel boundary source guard rejects forbidden hot path imports" {
    const source = @embedFile("linker.zig");
    inline for (.{
        "Treaty" ++ "Resolver",
        "Provider" ++ "Harness",
        "provider_" ++ "catalog",
        "morphism_" ++ "catalog",
        "closure_" ++ "graph",
        "string_match_" ++ "dispatch",
        "request_" ++ "token",
        "thread_" ++ "id",
    }) |forbidden| {
        try std.testing.expect(std.mem.indexOf(u8, source, forbidden) == null);
    }
}

