    };

    pub const ModuleRef = struct {
        format_version: u32 = world_module_ref_format_version,
        fingerprint_version: u32 = world_module_ref_fingerprint_version,
        module_ref_fingerprint: u64,
        boundary_module_fingerprint: u64,
